FIELDS = ['Use-case ID','Use-case name','Use-case overview','Actors','Trigger','Preconditions','Postconditions','Normal Flow (Steps 1..n)','Alternative Flows','Exceptions','Notes and Issues']


def scenario_markdown():
    lines = ['# Core use-case scenarios', '',
      'Current simplified model: 14 core goals. Routine validation, allocation and presentation remain scenario steps, not separate use cases. Six later lifecycle goals are specified below in the same document.', '',
      'Sources: assignment pp.1–4; PROJECT_SPECIFICATION.md §3; CO3001 Ch6 pp.16–20. Timing/battery thresholds are project design decisions, not numbers mandated by the assignment. Existing UC IDs are preserved.', '']
    for uid,filename,goal,pre,flow,alt,errors,post in CORE:
        actor = 'User' if int(uid[2:]) <= 7 else 'Operator'
        steps = '<br>'.join(f'{i}. {s.strip().rstrip(".")}.' for i,s in enumerate(flow.split(';'),1))
        supporting = {
          'UC03': '; Notification Service receives post-commit notifications',
          'UC04': '; IoT / Simulated Telemetry confirms unlock; Notification Service receives damage alerts',
          'UC05': '; IoT / Simulated Telemetry confirms safe return',
          'UC06': '; Notification Service receives reservation confirmation',
          'UC07': '; IoT / Simulated Telemetry confirms charging supply',
          'UC08': '; IoT / Simulated Telemetry supplies network observations',
          'UC10': '; IoT / Simulated Telemetry or Operator records departure confirmation',
          'UC11': '; IoT / Simulated Telemetry supplies alerts and safety confirmations',
          'UC12': '; IoT / Simulated Telemetry confirms supply changes',
        }.get(uid, '')
        values = [uid,goal,post,
          actor + supporting + '.',
          f'{actor} selects {goal}.',pre,post,steps,alt,errors,
          'The interface-level goal is unchanged by moving internal checks into prose. Cancel/Back before commit leaves state unchanged; later cancellation/stop actions retain their stated guards. No payment or separate technician application is introduced.']
        lines += [f'## {uid} — {goal}', '', '| Field | Scenario |', '|---|---|']
        lines += [f'| {field} | {value.replace(chr(124), chr(92)+chr(124))} |' for field,value in zip(FIELDS,values)]
        lines += ['']
    return '\n'.join(lines)
